import json
from copy import deepcopy

def solve():
    houses = [None] + [{'Name': None, 'Occupation': None, 'Car': None} for _ in range(6)]  # 1-based
    NAMES = ['Alice', 'Arnold', 'Eric', 'Peter', 'Bob', 'Carol']
    OCCS = ['engineer', 'artist', 'doctor', 'teacher', 'nurse', 'lawyer']
    CARS = ['chevrolet silverado', 'ford f150', 'honda civic', 'toyota camry', 'bmw 3 series', 'tesla model 3']

    # Pre-assign: Clue 1 - Ford F-150 is in the fifth house.
    houses[5]['Car'] = 'ford f150'

    names_rem = set(NAMES)
    occs_rem = set(OCCS)
    cars_rem = set(CARS)
    cars_rem.discard('ford f150')  # already used by house 5

    def consistent(hs):
        # Helper to find position of an attribute value
        def pos_of(key, val):
            for i in range(1, 7):
                if hs[i].get(key) == val:
                    return i
            return None

        # Per-house checks
        for i in range(1, 7):
            n = hs[i].get('Name')
            o = hs[i].get('Occupation')
            c = hs[i].get('Car')

            # Clue 1: Ford F-150 is in the fifth house
            if c == 'ford f150' and i != 5:
                return False
            if i == 5 and c is not None and c != 'ford f150':
                return False

            # Clue 2: Chevrolet Silverado not in the second house
            if i == 2 and c == 'chevrolet silverado':
                return False

            # Clue 4: Lawyer not in the fifth house
            if i == 5 and o == 'lawyer':
                return False

            # Clue 9: Carol not in the sixth house
            if i == 6 and n == 'Carol':
                return False

            # Clue 7: Doctor is Eric
            if n == 'Eric' and o is not None and o != 'doctor':
                return False
            if o == 'doctor' and n is not None and n != 'Eric':
                return False

            # Clue 10: Engineer is Bob
            if n == 'Bob' and o is not None and o != 'engineer':
                return False
            if o == 'engineer' and n is not None and n != 'Bob':
                return False

            # Clue 11: Toyota Camry owner is the nurse
            if c == 'toyota camry' and o is not None and o != 'nurse':
                return False
            if o == 'nurse' and c is not None and c != 'toyota camry':
                return False

            # Clue 14: Arnold is the artist
            if n == 'Arnold' and o is not None and o != 'artist':
                return False
            if o == 'artist' and n is not None and n != 'Arnold':
                return False

            # Clue 5: Nurse is directly left of artist
            if o == 'nurse':
                if i == 6:
                    return False
                o_r = hs[i+1].get('Occupation')
                if o_r is not None and o_r != 'artist':
                    return False
                # Since artist is Arnold, ensure right neighbor's name if assigned is Arnold
                n_r = hs[i+1].get('Name')
                if n_r is not None and n_r != 'Arnold':
                    return False
            if o == 'artist':
                if i == 1:
                    return False
                o_l = hs[i-1].get('Occupation')
                if o_l is not None and o_l != 'nurse':
                    return False

            # Clue 3: Honda Civic owner and Peter are next to each other.
            if c == 'honda civic':
                if i == 1:
                    n2 = hs[2].get('Name')
                    if n2 is not None and n2 != 'Peter':
                        return False
                elif i == 6:
                    n5 = hs[5].get('Name')
                    if n5 is not None and n5 != 'Peter':
                        return False
                else:
                    nprev = hs[i-1].get('Name')
                    nnext = hs[i+1].get('Name')
                    if (nprev is not None and nprev != 'Peter') and (nnext is not None and nnext != 'Peter'):
                        return False
            if n == 'Peter':
                if i == 1:
                    c2 = hs[2].get('Car')
                    if c2 is not None and c2 != 'honda civic':
                        return False
                elif i == 6:
                    c5 = hs[5].get('Car')
                    if c5 is not None and c5 != 'honda civic':
                        return False
                else:
                    cprev = hs[i-1].get('Car')
                    cnext = hs[i+1].get('Car')
                    if (cprev is not None and cprev != 'honda civic') and (cnext is not None and cnext != 'honda civic'):
                        return False

        # Clue 6: Carol right of Eric
        pos_eric = pos_of('Name', 'Eric')
        pos_carol = pos_of('Name', 'Carol')
        if pos_eric is not None and pos_carol is not None:
            if not (pos_carol > pos_eric):
                return False
        else:
            if pos_carol is not None and pos_eric is None:
                # ensure there is at least one position to the left for Eric
                if pos_carol <= 1:
                    return False
                any_left_spot = any(hs[j].get('Name') in (None, 'Eric') for j in range(1, pos_carol))
                if not any_left_spot:
                    return False
            if pos_eric is not None and pos_carol is None:
                any_right_spot = any(hs[j].get('Name') in (None, 'Carol') for j in range(pos_eric+1, 7))
                if not any_right_spot:
                    return False

        # Clue 8: Teacher left of nurse
        # Get positions of teacher and nurse (occupations)
        pos_teacher = pos_of('Occupation', 'teacher')
        pos_nurse = pos_of('Occupation', 'nurse')
        if pos_teacher is not None and pos_nurse is not None:
            if not (pos_teacher < pos_nurse):
                return False
        else:
            if pos_nurse is not None and pos_teacher is None:
                # ensure there is a spot to the left for teacher
                any_left = any(hs[j].get('Occupation') in (None, 'teacher') for j in range(1, pos_nurse))
                if not any_left:
                    return False
            if pos_teacher is not None and pos_nurse is None:
                # ensure there is a possible spot to the right for nurse that also can satisfy nurse-left-of-artist constraint
                any_right = False
                for j in range(pos_teacher + 1, 7):
                    if hs[j].get('Occupation') in (None, 'nurse'):
                        if j <= 5:
                            o_r = hs[j+1].get('Occupation')
                            n_r = hs[j+1].get('Name')
                            if (o_r is None or o_r == 'artist') and (n_r is None or n_r == 'Arnold'):
                                any_right = True
                                break
                if not any_right:
                    return False

        # Clue 12: One house between Peter and the lawyer
        pos_peter = pos_of('Name', 'Peter')
        pos_lawyer = pos_of('Occupation', 'lawyer')
        if pos_peter is not None and pos_lawyer is not None:
            if abs(pos_peter - pos_lawyer) != 2:
                return False
        else:
            if pos_peter is not None and pos_lawyer is None:
                candidates = [pos_peter - 2, pos_peter + 2]
                candidates = [k for k in candidates if 1 <= k <= 6]
                if not any(hs[k].get('Occupation') in (None, 'lawyer') for k in candidates):
                    return False
            if pos_lawyer is not None and pos_peter is None:
                candidates = [pos_lawyer - 2, pos_lawyer + 2]
                candidates = [k for k in candidates if 1 <= k <= 6]
                if not any(hs[k].get('Name') in (None, 'Peter') for k in candidates):
                    return False

        # Clue 13: One house between Tesla Model 3 and Bob
        # Car: 'tesla model 3', Name: 'Bob'
        pos_tesla = pos_of('Car', 'tesla model 3')
        pos_bob = pos_of('Name', 'Bob')
        if pos_tesla is not None and pos_bob is not None:
            if abs(pos_tesla - pos_bob) != 2:
                return False
        else:
            if pos_tesla is not None and pos_bob is None:
                candidates = [pos_tesla - 2, pos_tesla + 2]
                candidates = [k for k in candidates if 1 <= k <= 6]
                if not any(hs[k].get('Name') in (None, 'Bob') for k in candidates):
                    return False
            if pos_bob is not None and pos_tesla is None:
                candidates = [pos_bob - 2, pos_bob + 2]
                candidates = [k for k in candidates if 1 <= k <= 6]
                if not any(hs[k].get('Car') in (None, 'tesla model 3') for k in candidates):
                    return False

        return True

    def generate_candidates(i, names_rem, occs_rem, cars_rem, hs):
        candidates = []
        fixed_car = hs[i].get('Car')

        for name in list(names_rem):
            # Clue 9: Carol not in house 6
            if name == 'Carol' and i == 6:
                continue

            # Determine occupation options respecting fixed name-occupation mappings
            if name == 'Eric':
                if 'doctor' not in occs_rem:
                    continue
                occ_list = ['doctor']
            elif name == 'Bob':
                if 'engineer' not in occs_rem:
                    continue
                occ_list = ['engineer']
            elif name == 'Arnold':
                if 'artist' not in occs_rem:
                    continue
                occ_list = ['artist']
            else:
                # Exclude occupations that are uniquely tied to specific other names
                occ_list = [o for o in occs_rem if o not in ('doctor', 'engineer', 'artist')]

            # Adjust occupation options based on fixed car (Camry <-> Nurse)
            if fixed_car is not None:
                if fixed_car == 'toyota camry':
                    occ_list = [o for o in occ_list if o == 'nurse']
                else:
                    occ_list = [o for o in occ_list if o != 'nurse']

            for occ in occ_list:
                # Clue 5 adjacency implies artist not at position 1; nurse not at position 6
                if occ == 'artist' and i == 1:
                    continue
                if occ == 'nurse' and i == 6:
                    continue

                # Determine car options
                if fixed_car is not None:
                    car_list = [fixed_car]
                    # Check invalid pairing nurse/camry in case it's mismatched (should be filtered already)
                    if occ == 'nurse' and fixed_car != 'toyota camry':
                        continue
                    if occ != 'nurse' and fixed_car == 'toyota camry':
                        continue
                    if i == 2 and fixed_car == 'chevrolet silverado':
                        continue
                else:
                    # Build car list from remaining cars
                    car_list = list(cars_rem)
                    if occ == 'nurse':
                        if 'toyota camry' in cars_rem:
                            car_list = ['toyota camry']
                        else:
                            car_list = []
                    else:
                        if 'toyota camry' in car_list:
                            car_list.remove('toyota camry')
                    if i == 2 and 'chevrolet silverado' in car_list:
                        car_list.remove('chevrolet silverado')

                for car in car_list:
                    candidates.append((name, occ, car))

        return candidates

    def select_next_house(names_rem, occs_rem, cars_rem, hs):
        best_i = None
        best_candidates = None
        min_count = None
        for i in range(1, 7):
            if hs[i].get('Name') is None:
                cand = generate_candidates(i, names_rem, occs_rem, cars_rem, hs)
                if len(cand) == 0:
                    return None, []
                if min_count is None or len(cand) < min_count:
                    min_count = len(cand)
                    best_i = i
                    best_candidates = cand
        return best_i, best_candidates

    solution = None

    def backtrack(hs, names_rem, occs_rem, cars_rem):
        nonlocal solution
        if not consistent(hs):
            return False
        if len(names_rem) == 0:
            # All names assigned; ensure all occupations and cars assigned
            for i in range(1,7):
                if hs[i].get('Occupation') is None or hs[i].get('Car') is None:
                    return False
            solution = deepcopy(hs)
            return True

        i, candidates = select_next_house(names_rem, occs_rem, cars_rem, hs)
        if i is None:
            return False

        for (name, occ, car) in candidates:
            # assign
            prev_name = hs[i].get('Name')
            prev_occ = hs[i].get('Occupation')
            prev_car = hs[i].get('Car')
            fixed_car = prev_car  # remember if car was pre-assigned

            hs[i]['Name'] = name
            hs[i]['Occupation'] = occ
            # Assign car only if not fixed
            car_removed = None
            if fixed_car is None:
                hs[i]['Car'] = car
                car_removed = car
                cars_rem.remove(car)
            # Update remaining sets
            names_rem.remove(name)
            occs_rem.remove(occ)

            if consistent(hs):
                if backtrack(hs, names_rem, occs_rem, cars_rem):
                    return True

            # backtrack undo
            names_rem.add(name)
            occs_rem.add(occ)
            if car_removed is not None:
                cars_rem.add(car_removed)
            hs[i]['Name'] = prev_name
            hs[i]['Occupation'] = prev_occ
            hs[i]['Car'] = prev_car

        return False

    backtrack(houses, names_rem, occs_rem, cars_rem)
    return solution

def main():
    solved = solve()
    if not solved:
        output = {
            "solution": {
                "header": ["House", "Name", "Occupation", "CarModel"],
                "rows": []
            }
        }
    else:
        rows = []
        for i in range(1, 7):
            rows.append([
                str(i),
                solved[i]['Name'],
                solved[i]['Occupation'],
                solved[i]['Car']
            ])
        output = {
            "solution": {
                "header": ["House", "Name", "Occupation", "CarModel"],
                "rows": rows
            }
        }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()
